class Solution {
public:
    long long gridGame(vector<vector<int>>& grid) {
        int n = grid[0].size();
        long long totalTop = 0, totalBottom = 0;
        for (int i = 0; i < n; i++) {
            totalTop += grid[0][i];
            totalBottom += grid[1][i];
        }
        long long prefixTop = 0, prefixBottom = 0;
        long long ans = (long long)4e18;
        for (int k = 0; k < n; k++) {
            prefixTop += grid[0][k];
            long long topSum = totalTop - prefixTop;
            long long bottomSum = prefixBottom;
            long long robot2 = max(topSum, bottomSum);
            ans = min(ans, robot2);
            prefixBottom += grid[1][k];
        }
        return ans;
    }
};
